			drift = true
			continue
		}
		if deleted {
			continue
		}
		value, err := planMarker(marker)
		if err != nil {
			return false, err
		}
		backfill := reReplyCatalogPlanSeedVersion(models.JSONB{reReplyCatalogSeedVersionKey: value}) < reReplyCatalogSeedVersion
		if backfill {
